versions.code:
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Arial, sans-serif;
  background: #17130f;
  color: #fff4e6;
}
nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 20px 8%;
  border-bottom: 1px solid #45372b;
}
nav h2 { color: #d9a066; }
nav a { color: white; text-decoration: none; }
main { padding: 100px 10%; }
.tag { color: #d9a066; letter-spacing: 3px; }
h1 { font-size: clamp(42px, 7vw, 76px); margin: 20px 0; }
main > p:not(.tag) { color: #c8b9a8; }
button {
  margin-top: 20px;
  padding: 14px 24px;
  background: #d9a066;
  color: #17130f;
  border: 0;
  border-radius: 8px;
  cursor: pointer;
  font-weight: bold;
}
button:hover { background: #f0bd83; }
#message { color: #d9a066; margin-top: 20px; }

